/*
 * A042588  Numerators of continued fraction convergents to sqrt(823).
 * https://oeis.org/A042588
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cofr, frac, easy
 * Formula:   Numerators of convergents to the continued fraction of
 *            sqrt(823). Recurrence: p_{-2} = 0, p_{-1} = 1 p_k = a_k *
 *            p_{k-1} + p_{k-2} The partial quotients a_k are generated by the
 *            standard algorithm for the continued fraction of sqrt(823)
 * Range:     u8 n <= 2, u16 n <= 10, u32 n <= 19, u64 n <= 40, u128 n <= 81,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>

seq_t a(idx_t n)
{
    const idx_t D   = (idx_t)823;   /* discriminant */
    const idx_t a0  = (idx_t)28;    /* floor(sqrt(823)) */

    idx_t m  = 0;
    idx_t d  = 1;
    idx_t a_k = a0;

    seq_t p_im2 = (seq_t)0;   /* p_{-2} */
    seq_t p_im1 = (seq_t)1;   /* p_{-1} */

    for (idx_t i = 0; i <= n; ++i)
    {
        seq_t p_i = (seq_t)a_k * p_im1 + p_im2;
        p_im2 = p_im1;
        p_im1 = p_i;
        if (i == n)
            return p_i;

        /* next partial quotient */
        m  = d * a_k - m;
        d  = (D - m * m) / d;
        a_k = (a0 + m) / d;
    }
    /* unreachable */
    return (seq_t)0;
}
